/**
 * The LooseLeaf skin.
 *
 * Paper instead of chrome. LooseLeaf is a set of React components that look
 * drawn by hand: every surface is a sheet of paper, every line is a pen
 * stroke, colour is a highlighter rather than a fill. The charm is
 * decoration; the semantics are ordinary.
 *
 * What is ported here is the **token vocabulary**, not the artwork. The
 * vocabulary is the part worth keeping: a warm umber shadow ladder instead
 * of black alpha, a tight radius instead of a soft one, a dense space
 * ladder, a highlighter-yellow hover instead of a grey wash, and a
 * handwriting face with a real monospace for code.
 *
 * What is not ported: the drawn SVG outlines and the mascot. Those are the
 * "ink layer" — a separate, opt-in concern that a future `@aicl/ink` package
 * would own. This skin changes how AICL *looks*, not what AICL *does*.
 *
 * ## One palette, two modes
 *
 * The skin declares each colour once, with both modes:
 *
 *   --aicl-bg: #a8c8bb;                              <- the fallback
 *   --aicl-bg: light-dark(#a8c8bb, #232b27);         <- the real one
 *
 * `light-dark()` resolves against the element's used `color-scheme`, which
 * the contract sets from `data-theme` and which is inherited, so the mode
 * reaches the skin whether the attribute is on the skin or on an ancestor.
 *
 * Use it by putting the skin and the mode on the same element:
 *
 *   <div data-aicl-root data-aicl-theme="looseleaf" data-theme="dark">
 *
 * Without `data-theme`, the mode follows the system.
 */

[data-aicl-theme='looseleaf'] {
  /* ─── Type ────────────────────────────────────────────────────────
     The hand-drawn face reads larger than a UI face, so the scale steps
     up a notch. Kevin Sans is optional: install it and it is used, leave
     it out and the stack falls back to whatever handwriting face the
     system has. */
  --aicl-font-sans: 'Kevin Sans', 'Bradley Hand', 'Chalkboard SE', 'Segoe Print',
                    ui-rounded, system-ui, -apple-system, sans-serif;
  --aicl-font-mono: 'IBM Plex Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;

  --aicl-type-display:   19px;  --aicl-leading-display:   1.25;
  --aicl-type-title:     17px;  --aicl-leading-title:     1.35;
  --aicl-type-body:      16px;  --aicl-leading-body:      1.55;
  --aicl-type-secondary: 14px;  --aicl-leading-secondary: 1.5;
  --aicl-type-caption:   12px;  --aicl-leading-caption:   1.4;
  --aicl-type-micro:     11px;  --aicl-leading-micro:     1.3;

  --aicl-leading-tight:  1.25;
  --aicl-leading-snug:   1.4;
  --aicl-leading-normal: 1.55;

  /* Cut paper, not a rounded card. */
  --aicl-radius-sm: 2px;
  --aicl-radius-md: 3px;
  --aicl-radius-lg: 4px;
  --aicl-radius-xl: 6px;

  /* A denser ladder than the default: paper layouts are tighter. */
  --aicl-space-1: 4px;
  --aicl-space-2: 8px;
  --aicl-space-3: 12px;
  --aicl-space-4: 16px;
  --aicl-space-5: 20px;
  --aicl-space-6: 26px;
  --aicl-space-7: 34px;

  /* A hand-drawn control is taller and rounder to hold. */
  --aicl-control-height: 40px;
  --aicl-control-padding-x: 14px;
  --aicl-control-gap: 10px;
  --aicl-icon-size: 18px;

}

/* ─── Light ──────────────────────────────────────────────────────────
   A desk, then paper laid on it. Ink on the page. Marker orange is the
   one saturated colour: it is the accent, the primary action, the
   risograph ink. */
[data-aicl-theme='looseleaf'] {
  --aicl-bg: #a8c8bb;
  --aicl-bg: light-dark(#a8c8bb, #232b27);

  --aicl-surface: #f8f5ee;
  --aicl-surface: light-dark(#f8f5ee, #35332d);

  --aicl-surface-elevated: #fbf8f1;
  --aicl-surface-elevated: light-dark(#fbf8f1, #3d3a33);

  --aicl-surface-inset: #ece6da;
  --aicl-surface-inset: light-dark(#ece6da, #26241f);

  --aicl-surface-tint: #fbf6e9;
  --aicl-surface-tint: light-dark(#fbf6e9, #403c34);

  --aicl-sidebar: #f8f2de;
  --aicl-sidebar: light-dark(#f8f2de, #2b2a25);

  --aicl-overlay: rgb(58 44 30 / 0.34);
  --aicl-overlay: light-dark(rgb(58 44 30 / 0.34), rgb(12 10 8 / 0.6));

  /* Ink. */
  --aicl-text: #2a2420;
  --aicl-text: light-dark(#2a2420, #f0ead9);

  --aicl-text-muted: #4a433c;
  --aicl-text-muted: light-dark(#4a433c, #bdb5a3);

  --aicl-text-faint: #8e887f;
  --aicl-text-faint: light-dark(#8e887f, #8d8676);

  --aicl-text-link: #2c4f9e;
  --aicl-text-link: light-dark(#2c4f9e, #9db8f0);

  --aicl-text-inverse: #fbf8f1;
  --aicl-text-inverse: light-dark(#fbf8f1, #232b27);

  /* Pen marks. */
  --aicl-border: #8e887f;
  --aicl-border: light-dark(#8e887f, #57534a);

  --aicl-border-strong: #6b6660;
  --aicl-border-strong: light-dark(#6b6660, #6f6a5e);

  --aicl-border-focus: #2c4f9e;
  --aicl-border-focus: light-dark(#2c4f9e, #9db8f0);

  /* Marker orange. */
  --aicl-accent: #df6b3c;
  --aicl-accent: light-dark(#df6b3c, #e8854f);

  --aicl-accent-soft: color-mix(in srgb, #f8dc4c 62%, #f8f5ee);
  --aicl-accent-soft: light-dark(color-mix(in srgb, #f8dc4c 62%, #f8f5ee),
                                color-mix(in srgb, #f8dc4c 28%, #35332d));

  --aicl-accent-strong: #c4551f;
  --aicl-accent-strong: light-dark(#c4551f, #f0976a);

  --aicl-accent-fg: #fbf8f1;
  --aicl-accent-fg: light-dark(#fbf8f1, #232b27);

  /* Meaning. */
  --aicl-success: #3b7a4b;
  --aicl-success: light-dark(#3b7a4b, #7fbf8c);

  --aicl-warning: #a4502a;
  --aicl-warning: light-dark(#a4502a, #e0a463);

  --aicl-danger: #c2412d;
  --aicl-danger: light-dark(#c2412d, #e8776a);

  --aicl-info: #2c4f9e;
  --aicl-info: light-dark(#2c4f9e, #9db8f0);

  --aicl-tool-pending: #8e887f;
  --aicl-tool-pending: light-dark(#8e887f, #8d8676);

  --aicl-tool-running: #4a433c;
  --aicl-tool-running: light-dark(#4a433c, #bdb5a3);

  --aicl-tool-success: #3b7a4b;
  --aicl-tool-success: light-dark(#3b7a4b, #7fbf8c);

  --aicl-tool-error: #c2412d;
  --aicl-tool-error: light-dark(#c2412d, #e8776a);

  --aicl-tool-cancelled: #8e887f;
  --aicl-tool-cancelled: light-dark(#8e887f, #8d8676);

  /* Code and terminal. */
  --aicl-code-bg: #f4f7ef;
  --aicl-code-bg: light-dark(#f4f7ef, #232120);

  --aicl-code-fg: #2a2420;
  --aicl-code-fg: light-dark(#2a2420, #ece6d9);

  --aicl-code-border: #dcc8a3;
  --aicl-code-border: light-dark(#dcc8a3, #3a372f);

  --aicl-code-comment: #6b6660;
  --aicl-code-comment: light-dark(#6b6660, #8f949d);

  --aicl-code-keyword: #c2412d;
  --aicl-code-keyword: light-dark(#c2412d, #f6957d);

  --aicl-code-string: #3b7a4b;
  --aicl-code-string: light-dark(#3b7a4b, #abd98f);

  --aicl-code-number: #a4502a;
  --aicl-code-number: light-dark(#a4502a, #f7c370);

  --aicl-code-tag: #2c4f9e;
  --aicl-code-tag: light-dark(#2c4f9e, #80d6c6);

  --aicl-terminal-bg: #2a2420;
  --aicl-terminal-bg: light-dark(#2a2420, #1b1a18);

  --aicl-terminal-fg: #f8f5ee;
  --aicl-terminal-fg: light-dark(#f8f5ee, #ece6d9);

  --aicl-terminal-prompt: #8e887f;
  --aicl-terminal-prompt: light-dark(#8e887f, #8f949d);

  --aicl-bubble-user: #fbf6e9;
  --aicl-bubble-user: light-dark(#fbf6e9, #403c34);

  --aicl-ring: #2c4f9e;
  --aicl-ring: light-dark(#2c4f9e, #9db8f0);

  --aicl-selection-bg: color-mix(in srgb, #f8dc4c 62%, transparent);
  --aicl-selection-bg: light-dark(color-mix(in srgb, #f8dc4c 62%, transparent),
                                   color-mix(in srgb, #f8dc4c 32%, transparent));

  --aicl-hover-bg: color-mix(in srgb, #f8dc4c 45%, transparent);
  --aicl-hover-bg: light-dark(color-mix(in srgb, #f8dc4c 45%, transparent),
                               color-mix(in srgb, #f8dc4c 20%, transparent));

  --aicl-hover-bg-strong: color-mix(in srgb, #f8dc4c 70%, transparent);
  --aicl-hover-bg-strong: light-dark(color-mix(in srgb, #f8dc4c 70%, transparent),
                                      color-mix(in srgb, #f8dc4c 32%, transparent));
}

/* ─── Lift ──────────────────────────────────────────────────────────
   A sheet of paper does not blur. It sits up off the desk by a hard
   offset, the way a cut card casts a shadow the same shape as itself.
   Pressing the card moves it down onto that shadow. */
[data-aicl-theme='looseleaf'] {
  --aicl-border-width: 1.5px;
  --aicl-press-y: 2px;
  --aicl-enter-y: 10px;
  --aicl-enter-rotate: -0.7deg;
  --aicl-dialog-enter-y: 14px;
  --aicl-dialog-enter-scale: 0.97;
  --aicl-dialog-enter-rotate: -0.5deg;

  --aicl-shadow-1: 2px 2px 0 rgb(42 36 32 / 0.18);
  --aicl-shadow-2: 3px 3px 0 rgb(42 36 32 / 0.22);
  --aicl-shadow-3: 6px 6px 0 rgb(42 36 32 / 0.2);
  --aicl-shadow-4: 8px 8px 0 rgb(42 36 32 / 0.22);
  --aicl-shadow-5: 12px 12px 0 rgb(42 36 32 / 0.24);
  --aicl-shadow-6: 16px 16px 0 rgb(42 36 32 / 0.26);
}

/* ─── Dark ───────────────────────────────────────────────────────────
   The desk in lamplight: the same green, taken down; the paper, warmed to
   a low lamp rather than turned to grey. */
[data-aicl-theme='looseleaf'][data-theme='dark'] {
  --aicl-shadow-1: 2px 2px 0 rgb(0 0 0 / 0.45);
  --aicl-shadow-2: 3px 3px 0 rgb(0 0 0 / 0.5);
  --aicl-shadow-3: 6px 6px 0 rgb(0 0 0 / 0.55);
  --aicl-shadow-4: 8px 8px 0 rgb(0 0 0 / 0.58);
  --aicl-shadow-5: 12px 12px 0 rgb(0 0 0 / 0.6);
  --aicl-shadow-6: 16px 16px 0 rgb(0 0 0 / 0.64);
}

@media (prefers-color-scheme: dark) {
  [data-aicl-theme='looseleaf']:not([data-theme='light']) {
    --aicl-shadow-1: 2px 2px 0 rgb(0 0 0 / 0.45);
    --aicl-shadow-2: 3px 3px 0 rgb(0 0 0 / 0.5);
    --aicl-shadow-3: 6px 6px 0 rgb(0 0 0 / 0.55);
    --aicl-shadow-4: 8px 8px 0 rgb(0 0 0 / 0.58);
    --aicl-shadow-5: 12px 12px 0 rgb(0 0 0 / 0.6);
    --aicl-shadow-6: 16px 16px 0 rgb(0 0 0 / 0.64);
  }
}

/* Tooth on the desk. The page is the green blotter; components are the
   sheets laid on it. */
html[data-aicl-theme='looseleaf'],
html[data-aicl-theme='looseleaf'] body {
  background-color: var(--aicl-bg);
  background-image: radial-gradient(rgb(42 36 32 / 0.05) 0.7px, transparent 0.7px);
  background-size: 4px 4px;
}

/* The press, the highlighter, and the sheet that lifts when you write.
   These select the public slots. They do not add behaviour: a button is
   still a button, it just meets the desk when you hold it. */
[data-aicl-theme='looseleaf'] [data-aicl='button']:not([data-variant='ghost']):not([data-variant='link']),
[data-aicl-theme='looseleaf'] [data-aicl='composer'],
[data-aicl-theme='looseleaf'] [data-aicl='dialog'],
[data-aicl-theme='looseleaf'] [data-aicl='alert-dialog'],
[data-aicl-theme='looseleaf'] [data-aicl='suggestion-chip'],
[data-aicl-theme='looseleaf'] [data-aicl='scroll-to-bottom'] {
  box-shadow: var(--aicl-shadow-2);
}

[data-aicl-theme='looseleaf'] [data-aicl='button']:not(:disabled):active,
[data-aicl-theme='looseleaf'] [data-aicl='composer-submit']:not(:disabled):active,
[data-aicl-theme='looseleaf'] [data-aicl='suggestion-chip']:active {
  transform: translate(1px, var(--aicl-press-y));
  box-shadow: 1px 1px 0 rgb(42 36 32 / 0.28);
}

[data-aicl-theme='looseleaf'] [data-aicl='composer']:focus-within {
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 rgb(42 36 32 / 0.22);
  border-color: var(--aicl-text);
}

[data-aicl-theme='looseleaf'] [data-aicl='message'][data-alignment='end'] [data-aicl='part'][data-part='text'] {
  border: var(--aicl-border-width) solid var(--aicl-border);
  box-shadow: var(--aicl-shadow-1);
  background: var(--aicl-surface);
}

[data-aicl-theme='looseleaf'] [data-aicl='button'][data-variant='ghost']:hover,
[data-aicl-theme='looseleaf'] [data-aicl='suggestion-chip']:hover,
[data-aicl-theme='looseleaf'] [data-aicl='session-item']:hover {
  background: transparent;
  box-shadow: inset 0 -0.45em 0 var(--aicl-accent-soft);
}

@media (prefers-reduced-motion: reduce) {
  [data-aicl-theme='looseleaf'] {
    --aicl-press-y: 0px;
    --aicl-enter-y: 0px;
    --aicl-enter-rotate: 0deg;
    --aicl-dialog-enter-y: 0px;
    --aicl-dialog-enter-scale: 1;
    --aicl-dialog-enter-rotate: 0deg;
  }

  [data-aicl-theme='looseleaf'] [data-aicl='composer']:focus-within,
  [data-aicl-theme='looseleaf'] [data-aicl='button']:active {
    transform: none;
  }
}
